* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: #f4f5f7;
  color: #222;
}

main {
  max-width: 880px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

h1 {
  margin-top: 0;
}

h2 {
  font-size: 1.1rem;
  margin: 0 0 12px;
}

